package com.smartseating.ui;

import com.smartseating.dao.RoomTemplateDAO;
import com.smartseating.model.*;
import com.smartseating.service.PrintService;
import com.smartseating.util.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;

public class RoomTemplateFrame extends AppFrame {
    private final RoomTemplateDAO dao=new RoomTemplateDAO();private final JTextField name=new JTextField(),start=new JTextField("101"),count=new JTextField("20"),rows=new JTextField("5"),columns=new JTextField("8"),building=new JTextField("Main Block"),floor=new JTextField("1");private final JTable table=new JTable();private RoomTemplate selected;
    public RoomTemplateFrame(User user){super("Room Templates",user);UI.frame(this,1050,650);build();refresh();}
    private void build(){content.add(title("Room Templates"),BorderLayout.NORTH);JPanel form=UI.formPanel();UI.addField(form,0,"Template Name",name);UI.addField(form,1,"Starting Room",start);UI.addField(form,2,"Number of Rooms",count);UI.addField(form,3,"Rows",rows);UI.addField(form,4,"Columns",columns);UI.addField(form,5,"Building",building);UI.addField(form,6,"Floor",floor);JPanel a=new JPanel(new GridLayout(2,3,7,7));a.setOpaque(false);JButton save=button("SAVE TEMPLATE",UI.TEAL),load=button("LOAD TEMPLATE",UI.BLUE),del=button("DELETE TEMPLATE",new Color(190,66,66)),clear=button("CLEAR",UI.MUTED),print=button("PRINT",UI.ORANGE);for(JButton b:new JButton[]{save,load,del,clear,print})a.add(b);GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.gridy=7;g.gridwidth=2;g.fill=GridBagConstraints.HORIZONTAL;g.insets=new Insets(14,6,6,6);form.add(a,g);content.add(white(form),BorderLayout.WEST);UI.tableStyle(table);content.add(white(UI.scroll(table)),BorderLayout.CENTER);save.addActionListener(e->save());load.addActionListener(e->load());del.addActionListener(e->delete());clear.addActionListener(e->clear());print.addActionListener(e->PrintService.print("Room Template List",text()));table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&table.getSelectedRow()>=0)select();});if("TEACHER".equals(currentUser.getRole())){save.setEnabled(false);del.setEnabled(false);}}
    private RoomTemplate read(){return new RoomTemplate(0,Validation.text(name.getText(),"Template name"),Validation.text(start.getText(),"Starting room"),Validation.positive(count.getText(),"Number of rooms"),Validation.positive(rows.getText(),"Rows"),Validation.positive(columns.getText(),"Columns"),Validation.text(building.getText(),"Building"),Validation.positive(floor.getText(),"Floor"));}private void save(){try{RoomTemplate x=read();if(selected==null)dao.save(x);else{x.setId(selected.getId());dao.update(x);}clear();refresh();}catch(Exception ex){error(ex);}}private void load(){if(selected==null)throw new IllegalArgumentException("Select a template first.");start.setText(selected.getStartingRoom());count.setText(String.valueOf(selected.getNumberOfRooms()));rows.setText(String.valueOf(selected.getRows()));columns.setText(String.valueOf(selected.getColumns()));building.setText(selected.getBuilding());floor.setText(String.valueOf(selected.getFloor()));}private void delete(){try{if(selected==null)throw new IllegalArgumentException("Select a template first.");if(confirm("Delete selected template?")){dao.delete(selected.getId());clear();refresh();}}catch(Exception ex){error(ex);}}private void select(){int r=table.getSelectedRow();selected=new RoomTemplate((int)table.getValueAt(r,0),String.valueOf(table.getValueAt(r,1)),String.valueOf(table.getValueAt(r,2)),Integer.parseInt(String.valueOf(table.getValueAt(r,3))),Integer.parseInt(String.valueOf(table.getValueAt(r,4))),Integer.parseInt(String.valueOf(table.getValueAt(r,5))),String.valueOf(table.getValueAt(r,6)),Integer.parseInt(String.valueOf(table.getValueAt(r,7))));name.setText(selected.getTemplateName());load();}private void clear(){selected=null;name.setText("");start.setText("101");count.setText("20");rows.setText("5");columns.setText("8");building.setText("Main Block");floor.setText("1");table.clearSelection();}private void refresh(){try{DefaultTableModel m=new DefaultTableModel(new Object[]{"ID","Name","Starting","Rooms","Rows","Columns","Building","Floor"},0);for(RoomTemplate x:dao.findAll())m.addRow(new Object[]{x.getId(),x.getTemplateName(),x.getStartingRoom(),x.getNumberOfRooms(),x.getRows(),x.getColumns(),x.getBuilding(),x.getFloor()});table.setModel(m);UI.tableStyle(table);}catch(Exception ex){error(ex);}}private String text(){StringBuilder b=new StringBuilder("ROOM TEMPLATE LIST\n\n");for(int i=0;i<table.getRowCount();i++)b.append(table.getValueAt(i,1)).append(" | ").append(table.getValueAt(i,3)).append(" rooms | ").append(table.getValueAt(i,4)).append("x").append(table.getValueAt(i,5)).append("\n");return b.toString();}
}
